var cam = UnityEngine.Camera.main;
var sb = new System.Text.StringBuilder();
if (cam != null)
    sb.AppendLine($"Cam: pos={cam.transform.position}, rot={cam.transform.rotation.eulerAngles}, cullingMask={cam.cullingMask}, fov={cam.fieldOfView}");
else
    sb.AppendLine("Cam: NULL");

foreach(var go in UnityEngine.Object.FindObjectsByType<UnityEngine.GameObject>(UnityEngine.FindObjectsInactive.Include, UnityEngine.FindObjectsSortMode.None))
{
    if (go.name.Contains("Aeron") || go.name.Contains("Guard"))
    {
        sb.AppendLine($"Found: {go.name}, active={go.activeInHierarchy}, pos={go.transform.position}, layer={go.layer}");
        var smr = go.GetComponentInChildren<UnityEngine.SkinnedMeshRenderer>();
        if (smr != null)
        {
            sb.AppendLine($"  SMR: mesh={smr.sharedMesh?.name}, boundsCenter={smr.bounds.center}, boundsExtents={smr.bounds.extents}, enabled={smr.enabled}, mat={smr.sharedMaterial?.name}");
        }
    }
}
System.IO.File.WriteAllText("c:/projects/LAST-GOD/scratch/diag_out.txt", sb.ToString());
